static const size_t NOT_FOUND = static_cast<size_t>(-1);

template <typename T>
size_t Find(const T& value, const T* arr, size_t size)
{
    for (size_t i = 0; i < size; ++i) {
        if (arr[i] == value) {
            return i;
        }
    }
    return NOT_FOUND;
}

int myInt = 3;
int intArray[] = {1, 2, 3, 4};
const size_t sizeIntArray = std::size(intArray);

size_t res = Find(myInt, intArray, sizeIntArray);       // 推导 T=int
res = Find<int>(myInt, intArray, sizeIntArray);         // 显式指定 T=int

double myDouble = 5.6;
double doubleArray[] = {1.2, 3.4, 5.7, 7.5};
size_t res = Find(myDouble, doubleArray, std::size(doubleArray)); // 推导 T=double

SpreadsheetCell cell1(10);
SpreadsheetCell cellArray[] = {SpreadsheetCell(4), SpreadsheetCell(10)};
size_t res = Find(cell1, cellArray, std::size(cellArray));
